'use client';

import { useState } from 'react';

import { UserIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';

import { Swap } from './_parts/motion-parts';
import { PEOPLE, personOf } from './_parts/people';
import { keyOf, SUBTASKS, type Subtask } from './_parts/subtask-data';
import {
  isStatusId,
  PersonAvatar,
  StatusGlyph,
  statusOf,
  STATUSES,
  type StatusId,
} from './_parts/subtask-parts';

const UNASSIGNED = 'unassigned';

const ROW_BUTTON =
  'hover:bg-foreground/5 focus-visible:ring-ring/25 data-popup-open:bg-foreground/5 inline-flex shrink-0 cursor-pointer items-center justify-center rounded-md outline-none focus-visible:ring-[3px]';

function patched(
  subtasks: Subtask[],
  subtaskId: string,
  changes: Partial<Subtask>
) {
  return subtasks.map((subtask) => {
    if (subtask.id !== subtaskId) {
      return subtask;
    }
    return { ...subtask, ...changes };
  });
}

function assigneeIdOf(value: unknown) {
  if (value === UNASSIGNED) {
    return undefined;
  }
  const isPerson = PEOPLE.some((person) => person.id === value);
  if (isPerson) {
    return String(value);
  }
  return undefined;
}

function StatusMenu({
  subtask,
  onPick,
}: {
  subtask: Subtask;
  onPick: (status: StatusId) => void;
}) {
  const meta = statusOf(subtask.status);

  function pick(value: unknown) {
    if (isStatusId(value)) {
      onPick(value);
    }
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        aria-label={`Status of ${subtask.title}: ${meta.name}. Change status`}
        className={cn(ROW_BUTTON, 'size-7')}
      >
        <Swap swapKey={subtask.status}>
          <StatusGlyph status={subtask.status} />
        </Swap>
      </DropdownMenuTrigger>
      <DropdownMenuContent className='w-44'>
        <DropdownMenuRadioGroup value={subtask.status} onValueChange={pick}>
          {STATUSES.map((status) => (
            <DropdownMenuRadioItem
              key={status.id}
              value={status.id}
              closeOnClick
            >
              <StatusGlyph status={status.id} />
              {status.name}
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function AssigneeFace({ assigneeId }: { assigneeId?: string }) {
  if (!assigneeId) {
    return (
      <span className='hairline-border border-foreground/30 text-muted-foreground flex size-5 items-center justify-center rounded-full border-dashed'>
        <UserIcon className='size-3' />
      </span>
    );
  }
  return <PersonAvatar person={personOf(assigneeId)} />;
}

function assigneeNameOf(assigneeId?: string) {
  if (!assigneeId) {
    return 'nobody';
  }
  return personOf(assigneeId).name;
}

function AssigneeMenu({
  subtask,
  onPick,
}: {
  subtask: Subtask;
  onPick: (assigneeId: string | undefined) => void;
}) {
  const value = subtask.assigneeId ?? UNASSIGNED;

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        aria-label={`${subtask.title} is assigned to ${assigneeNameOf(subtask.assigneeId)}. Change assignee`}
        className={cn(ROW_BUTTON, 'size-7 rounded-full')}
      >
        <Swap swapKey={value}>
          <AssigneeFace assigneeId={subtask.assigneeId} />
        </Swap>
      </DropdownMenuTrigger>
      <DropdownMenuContent align='end' className='w-48'>
        <DropdownMenuRadioGroup
          value={value}
          onValueChange={(next) => onPick(assigneeIdOf(next))}
        >
          <DropdownMenuRadioItem value={UNASSIGNED} closeOnClick>
            <AssigneeFace />
            No assignee
          </DropdownMenuRadioItem>
          {PEOPLE.map((person) => (
            <DropdownMenuRadioItem
              key={person.id}
              value={person.id}
              closeOnClick
            >
              <PersonAvatar person={person} />
              {person.name}
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function countWith(subtasks: Subtask[], status: StatusId) {
  return subtasks.filter((subtask) => subtask.status === status).length;
}

function summaryOf(subtasks: Subtask[]) {
  const phrases: string[] = [];
  for (const status of STATUSES) {
    const count = countWith(subtasks, status.id);
    if (count === 0) {
      continue;
    }
    phrases.push(`${count} ${status.name.toLowerCase()}`);
  }
  return phrases.join(', ');
}

function StatusBreakdown({ subtasks }: { subtasks: Subtask[] }) {
  const summary = summaryOf(subtasks);

  return (
    <div className='flex flex-col gap-1.5'>
      <span aria-hidden='true' className='flex gap-0.5'>
        {subtasks.map((subtask) => {
          const segmentStyle = {
            backgroundColor: statusOf(subtask.status).color,
          } as React.CSSProperties;
          return (
            <span
              key={subtask.id}
              style={segmentStyle}
              className='h-1.5 flex-1 rounded-full opacity-80 transition-[background-color] duration-200'
            />
          );
        })}
      </span>
      <p className='text-muted-foreground text-xs'>{summary}</p>
    </div>
  );
}

export default function Subtask04() {
  const [subtasks, setSubtasks] = useState(SUBTASKS.slice(0, 6));

  function patch(subtaskId: string, changes: Partial<Subtask>) {
    setSubtasks((current) => patched(current, subtaskId, changes));
  }

  return (
    <section aria-label='Sub-tasks with status' className='w-full max-w-md'>
      <header className='flex flex-col gap-3 px-1.5'>
        <h3 className='text-sm font-medium'>Sub-tasks</h3>
        <StatusBreakdown subtasks={subtasks} />
      </header>
      <ul className='mt-3 flex flex-col'>
        {subtasks.map((subtask) => {
          const isFinished = subtask.status === 'done';
          return (
            <li
              key={subtask.id}
              className='flex h-10 items-center gap-2 rounded-lg px-1'
            >
              <StatusMenu
                subtask={subtask}
                onPick={(status) => patch(subtask.id, { status })}
              />
              <span className='text-muted-foreground w-16 shrink-0 text-xs tabular-nums'>
                {keyOf(subtask.number)}
              </span>
              <span
                className={cn(
                  'min-w-0 flex-1 truncate text-[13px] transition-colors duration-200',
                  isFinished && 'text-muted-foreground'
                )}
              >
                {subtask.title}
              </span>
              <AssigneeMenu
                subtask={subtask}
                onPick={(assigneeId) => patch(subtask.id, { assigneeId })}
              />
            </li>
          );
        })}
      </ul>
    </section>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type MotionProps,
  type Transition,
  type Variants,
} from 'motion/react';
import { useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';

export const EASE_OUT_STRONG: [number, number, number, number] = [
  0.23, 1, 0.32, 1,
];

export const ENTER: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

export const EXIT: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

export type PresenceProps = Pick<
  MotionProps,
  'initial' | 'animate' | 'exit' | 'transition'
>;

const HEIGHT_PRESENCE: PresenceProps = {
  initial: { height: 0, opacity: 0 },
  animate: { height: 'auto', opacity: 1 },
  exit: { height: 0, opacity: 0, transition: EXIT },
  transition: ENTER,
};

const FADE_PRESENCE: PresenceProps = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT },
  transition: ENTER,
};

/** Rows that arrive or leave a list: their height opens and closes so the rows after them slide. */
export function heightPresenceOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_PRESENCE;
  }
  return HEIGHT_PRESENCE;
}

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

const SWAP_VARIANTS: Variants = {
  hidden: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  shown: { opacity: 1, scale: 1, filter: 'blur(0px)' },
};

const FADE_VARIANTS: Variants = {
  hidden: { opacity: 0 },
  shown: { opacity: 1 },
};

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

type SwapProps = {
  swapKey: string;
  children: React.ReactNode;
  className?: string;
};

/** An icon or a short label that becomes another one in place. */
export function Swap({ swapKey, children, className }: SwapProps) {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <span className={cn('relative inline-flex', className)}>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={swapKey}
          variants={swapVariantsOf(shouldReduceMotion)}
          initial='hidden'
          animate='shown'
          exit='hidden'
          transition={SWAP_TRANSITION}
          className='inline-flex'
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

const COUNT_SLIDE = 8;

const COUNT_TRANSITION: Transition = { duration: 0.18, ease: EASE_OUT_STRONG };

const COUNT_VARIANTS: Variants = {
  enter: (offset: number) => ({ y: offset, opacity: 0 }),
  center: { y: 0, opacity: 1 },
  leave: (offset: number) => ({ y: -offset, opacity: 0 }),
};

function directionOf(previous: number, next: number) {
  if (next < previous) {
    return -1;
  }
  return 1;
}

function offsetOf(direction: number, shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return 0;
  }
  return direction * COUNT_SLIDE;
}

type RollingCountProps = {
  value: number;
  /** Writes the value, such as a duration; the digits still roll on the number. */
  format?: (value: number) => string;
  className?: string;
};

function plainNumber(value: number) {
  return String(value);
}

/** A figure the person just changed: the new digits slide in from the side of the change. */
export function RollingCount({
  value,
  format = plainNumber,
  className,
}: RollingCountProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const [previous, setPrevious] = useState(value);
  const [direction, setDirection] = useState(1);

  if (previous !== value) {
    setDirection(directionOf(previous, value));
    setPrevious(value);
  }

  const offset = offsetOf(direction, shouldReduceMotion);

  return (
    <span
      className={cn(
        'relative inline-flex overflow-hidden tabular-nums',
        className
      )}
    >
      <AnimatePresence mode='popLayout' initial={false} custom={offset}>
        <motion.span
          key={value}
          custom={offset}
          variants={COUNT_VARIANTS}
          initial='enter'
          animate='center'
          exit='leave'
          transition={COUNT_TRANSITION}
          className='inline-block'
        >
          {format(value)}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

